#include <Cellerator/compiler/ir/planning/implement_resource_and_stage_inventory_alternatives_v1.hh>
#include <algorithm>
namespace cellerator::compiler::ir::planning::v1 {
resource_inventory_status_v1 validate_resource_inventory_alternative_v1(const resource_inventory_alternative_v1&v) noexcept{if((v.alternative.low==0&&v.alternative.high==0)||!v.stages||!v.stage_count)return resource_inventory_status_v1::invalid_argument;std::uint64_t p=0,t=0;std::uint32_t l=0,s=0;for(std::uint32_t i=0;i<v.stage_count;++i){auto&x=v.stages[i];if(x.stage.low==0&&x.stage.high==0)return resource_inventory_status_v1::invalid_identity;if(!x.workspace_alignment||(x.workspace_alignment&(x.workspace_alignment-1u)))return resource_inventory_status_v1::invalid_alignment;if(x.flags&~15u)return resource_inventory_status_v1::invalid_flags;p+=x.persistent_bytes;t+=x.transfer_bytes;l+=x.launch_count;s=std::max(s,x.stream_count);}if(p!=v.persistent_bytes||t!=v.total_transfer_bytes||l!=v.total_launch_count||s!=v.required_stream_count)return resource_inventory_status_v1::aggregate_mismatch;return resource_inventory_status_v1::ok;}
resource_inventory_status_v1 compare_candidate_resources_v1(const resource_inventory_alternative_v1&v,const catalog_v3::candidate_descriptor_v3&c) noexcept{auto status=validate_resource_inventory_alternative_v1(v);if(status!=resource_inventory_status_v1::ok)return status;if(v.persistent_bytes!=c.resources.persistent_bytes||v.peak_transient_bytes!=c.resources.transient_bytes||v.stage_count!=c.stage_count)return resource_inventory_status_v1::catalog_mismatch;for(std::uint32_t i=0;i<v.stage_count;++i)if(v.stages[i].launch_count!=c.stages[i].launch_count)return resource_inventory_status_v1::catalog_mismatch;return resource_inventory_status_v1::ok;}
}
